CREATE     PROCEDURE [synapse_fo].[usp_Update_SYSTEMPARAMETERS]
AS
/*
	Created by: Raj Maddala
	Created on: 2023-05-15 10:30:52
	Description: Update stored procedure for SYSTEMPARAMETERS from synapse finops datalake to BI
*/
BEGIN
	UPDATE tgt SET 
		tgt.[CHARTOFACCOUNTSDELIMITER] = stg.[CHARTOFACCOUNTSDELIMITER],
		tgt.[DataLakeModified_DateTime] = stg.[DataLakeModified_DateTime],
		--tgt.[FileName] = stg.[FileName],
		--tgt.[KEY_] = stg.[KEY_],
		tgt.[LastProcessedChange_DateTime] = stg.[LastProcessedChange_DateTime],
		--tgt.[LSN] = stg.[LSN],
		tgt.[MODIFIEDBY] = stg.[MODIFIEDBY],
		tgt.[MODIFIEDDATETIME] = stg.[MODIFIEDDATETIME],
		tgt.[ODATAALLOWNULLFORENUMKEYVALUE] = stg.[ODATAALLOWNULLFORENUMKEYVALUE],
		tgt.[ODATABUILDMETADATACACHEONAOSSTARTUP] = stg.[ODATABUILDMETADATACACHEONAOSSTARTUP],
		tgt.[PARTITION] = stg.[PARTITION],
		tgt.[POWERPORTALANONYMOUSUSERID] = stg.[POWERPORTALANONYMOUSUSERID],
		tgt.[RECID] = stg.[RECID],
		tgt.[RECVERSION] = stg.[RECVERSION],
		tgt.[SRSMAXROW_CN] = stg.[SRSMAXROW_CN],
		--tgt.[SysRowId] = stg.[SysRowId],
		tgt.[SYSTEMCURRENCYCODE] = stg.[SYSTEMCURRENCYCODE],
		tgt.[SYSTEMEXCHANGERATETYPE] = stg.[SYSTEMEXCHANGERATETYPE],
		tgt.[SYSTEMLANGUAGEID] = stg.[SYSTEMLANGUAGEID],
		tgt.[SYSTEMLEGALTERMSURL] = stg.[SYSTEMLEGALTERMSURL],
		tgt.[SYSTEMLINENUMBERINCREMENT] = stg.[SYSTEMLINENUMBERINCREMENT],
		tgt.[SYSTEMPRIVACYSTATEMENTURL] = stg.[SYSTEMPRIVACYSTATEMENTURL],
		tgt.[THAISOFTWARESEQNO] = stg.[THAISOFTWARESEQNO],
		tgt.[USEADVCERTIFICATESTORE] = stg.[USEADVCERTIFICATESTORE],
		tgt.[USELEGACYQUERYRELATIONS] = stg.[USELEGACYQUERYRELATIONS]
	 FROM [synapse_fo].[SYSTEMPARAMETERS] tgt
		INNER JOIN [staging_fo].[SYSTEMPARAMETERS] stg
			ON  stg.[RECID] = tgt.[RECID] 
		
END
